"""``rasa tools skills`` — install and list Rasa agent skills per engine.

Resolution:
- **mantle** — skills vendored under ``skills_data/mantle/`` in the wheel;
  install offline, version-exact, no network.
- **calm** — GitHub list + raw download from the agent-skills repository
  (same path as pre-manifest ``rasa tools init skills``), including the
  frontmatter ``rasa_version`` compatibility warn/skip.

``rasa tools init skills`` remains a deprecated alias of install (defaults to
calm, matching historical behaviour).
"""

from __future__ import annotations

import argparse
import json
import sys
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path
from typing import Any, Dict, List, Optional, Set, Tuple

import questionary
from rich.console import Console
from rich.panel import Panel
from rich.table import Table

from rasa.cli.tools.constants import (
    AGENT_SKILL_ENTRYPOINT,
    AGENT_SKILL_REFERENCES_DIR,
    AGENT_SKILLS_API_URL,
    AGENT_SKILLS_RAW_URL,
    AGENT_SKILLS_REFERENCE_RAW_URL,
    AGENT_SKILLS_REFERENCES_API_URL,
    AGENT_SKILLS_REPO,
    BUNDLED_SKILLS_DIRNAME,
    ENGINE_CALM,
    ENGINE_MANTLE,
    HTTP_TIMEOUT,
    IDE_DISPLAY_NAMES,
    IDE_SKILLS_BASE,
    SUPPORTED_ENGINES,
    SUPPORTED_IDES,
    WIZARD_STYLE,
)
from rasa.cli.tools.models import AgentSkillInfo
from rasa.cli.tools.utils import (
    _precheck,
    _resolve_ides,
    _resolve_project_dir,
    restore_blocking_io,
)
from rasa.version import __version__ as rasa_version

console = Console()

# Entrypoints ==========================================================================


def skills_install(args: argparse.Namespace) -> None:
    """Entrypoint for `rasa tools skills install`."""
    _precheck()

    project_dir = _resolve_project_dir(
        getattr(args, "project_path", None), validate_exists=True
    )
    non_interactive = getattr(args, "yes", False)

    engine = getattr(args, "engine", None)
    if engine is None:
        if non_interactive:
            console.print(
                "[red]✖[/red] No engine specified. "
                f"Pass one of: [bold]{', '.join(SUPPORTED_ENGINES)}[/bold], "
                "e.g. [bold]rasa tools skills install mantle[/bold]."
            )
            sys.exit(1)
        engine = _ask_engine()

    ides = _resolve_ides(getattr(args, "ides", None), project_dir)
    if not ides:
        if non_interactive:
            _print_no_ides_hint()
            sys.exit(1)
        ides = _ask_ides()

    if not install_agent_skills(
        project_dir,
        ides,
        non_interactive=non_interactive,
        engine=engine,
    ):
        sys.exit(1)


def skills_list(args: argparse.Namespace) -> None:
    """Entrypoint for `rasa tools skills list`."""
    _precheck()

    requested = getattr(args, "engine", None)
    engines = [requested] if requested else list(SUPPORTED_ENGINES)

    listed_any = False
    for engine_name in engines:
        if engine_name == ENGINE_MANTLE:
            bundled = _load_bundled_skills(engine_name)
            if not bundled:
                console.print(
                    f"  [red]✖[/red] No agent skills are bundled with this "
                    f"Rasa version for engine [bold]{engine_name}[/bold]."
                )
                if requested is not None:
                    sys.exit(1)
                continue
            _print_bundled_skills_table(engine_name, bundled)
            listed_any = True
            continue

        if engine_name == ENGINE_CALM:
            names = _fetch_skill_names_from_repo()
            if not names:
                if requested is not None:
                    sys.exit(1)
                console.print(
                    "  [yellow]⚠[/yellow]  Could not list calm skills "
                    "(network fetch failed). Continuing with other engines."
                )
                continue
            _print_calm_skills_table(names)
            listed_any = True
            continue

        console.print(
            f"  [red]✖[/red] Unknown engine [bold]{engine_name}[/bold]. "
            f"Available: {', '.join(SUPPORTED_ENGINES)}."
        )
        sys.exit(1)

    if not listed_any:
        sys.exit(1)


def skills_tools(args: argparse.Namespace) -> None:
    """Entrypoint for the deprecated `rasa tools init skills`."""
    console.print(
        "[yellow]`rasa tools init skills` is deprecated — "
        "use `rasa tools skills install` instead.[/yellow]"
    )
    _precheck()

    project_dir = _resolve_project_dir(
        getattr(args, "project_path", None), validate_exists=True
    )

    ides = _resolve_ides(getattr(args, "ides", None), project_dir)
    if not ides:
        _print_no_ides_hint()
        sys.exit(1)

    non_interactive = getattr(args, "yes", False)
    # Historical default: calm GitHub skills.
    if not install_agent_skills(
        project_dir,
        ides,
        non_interactive=non_interactive,
        engine=ENGINE_CALM,
    ):
        sys.exit(1)


# Orchestrators ========================================================================


def install_agent_skills(
    project_dir: Path,
    ides: List[str],
    non_interactive: bool = False,
    engine: Optional[str] = None,
) -> bool:
    """Install agent skills for *engine* into each selected IDE directory.

    Args:
        project_dir: Absolute path to the Rasa project root.
        ides: List of IDE identifiers to install skills for.
        non_interactive: Skip confirmation prompts; overwrite existing skills;
            for calm, skip incompatible skills silently.
        engine: ``"mantle"`` (bundled) or ``"calm"`` (GitHub fetch). When
            ``None``, defaults to calm (historical behaviour for callers that
            predate the engine argument).

    Returns:
        ``False`` on hard failure (unknown engine, empty fetch, no downloads);
        ``True`` on success or intentional skip.
    """
    console.print()

    resolved = engine or ENGINE_CALM
    if resolved == ENGINE_MANTLE:
        bundled = _load_bundled_skills(resolved)
        if not bundled:
            console.print(
                f"  [red]✖[/red] No agent skills are bundled with this Rasa "
                f"version for engine [bold]{resolved}[/bold]."
            )
            return False
        return _install_bundled_skills(
            bundled, resolved, project_dir, ides, non_interactive
        )

    if resolved == ENGINE_CALM:
        return _install_calm_from_repo(project_dir, ides, non_interactive)

    console.print(
        f"  [red]✖[/red] Unknown engine [bold]{resolved}[/bold]. "
        f"Available: {', '.join(SUPPORTED_ENGINES)}."
    )
    return False


def _install_bundled_skills(
    skills: List[AgentSkillInfo],
    engine: str,
    project_dir: Path,
    ides: List[str],
    non_interactive: bool,
) -> bool:
    """Copy vendored skills for *engine* to each IDE directory."""
    destinations = _resolve_destinations(project_dir, ides)
    if destinations is None:
        return True

    existing = _find_existing_skills(destinations)
    if existing and not non_interactive:
        if not _confirm_overwrite_skills(existing):
            console.print("  Skipping skill installation.")
            return True

    console.print(
        f"  Installing [bold]{len(skills)}[/bold] agent skills for "
        f"[bold]{engine}[/bold] bundled with Rasa [bold]{rasa_version}[/bold]…"
    )
    _write_skills_to_disk(skills, destinations)
    _print_install_summary(destinations)
    return True


def _install_calm_from_repo(
    project_dir: Path,
    ides: List[str],
    non_interactive: bool,
) -> bool:
    """Download CALM skills from the agent-skills GitHub repo (pre-manifest)."""
    skill_names = _fetch_skill_names_from_repo()
    if not skill_names:
        return False

    destinations = _resolve_destinations(project_dir, ides)
    if destinations is None:
        return True

    existing = _find_existing_skills(destinations)
    if existing and not non_interactive:
        if not _confirm_overwrite_skills(existing):
            console.print("  Skipping skill installation.")
            return True

    console.print(f"  Downloading [bold]{len(skill_names)}[/bold] agent skills…")
    downloaded_skills = _download_skills_from_repo(skill_names)
    if not downloaded_skills:
        return False

    compatible, incompatible = _partition_by_compatibility(downloaded_skills)

    install_incompatible = False
    if incompatible:
        _warn_incompatible_skills(incompatible, rasa_version)
        if non_interactive:
            console.print("  Skipping incompatible skills (non-interactive mode).")
        else:
            install_incompatible = _confirm_install_incompatible()

    skills_to_install = list(compatible)
    if install_incompatible:
        skills_to_install.extend(incompatible)
    if not skills_to_install:
        console.print("  No compatible skills to install.")
        return True

    incompatible_names: Set[str] = (
        {skill.name for skill in incompatible} if install_incompatible else set()
    )
    _write_skills_to_disk(skills_to_install, destinations, incompatible_names)
    _print_install_summary(destinations)
    return True


def _resolve_destinations(
    project_dir: Path, ides: List[str]
) -> Optional[Dict[str, Path]]:
    """Map each selected IDE to its skills directory under *project_dir*."""
    destinations: Dict[str, Path] = {
        ide: project_dir / base for ide, base in IDE_SKILLS_BASE.items() if ide in ides
    }
    if not destinations:
        console.print(
            "  [yellow]ℹ[/yellow]  "
            "No IDEs with a supported skills location selected."
        )
        return None
    return destinations


def _print_install_summary(destinations: Dict[str, Path]) -> None:
    """Print the success panel listing every install destination."""
    installed_dirs = "\n".join(f"  • {dest_dir}" for dest_dir in destinations.values())
    console.print(
        Panel(
            "[bold green]Agent skills installed successfully.[/bold green]\n\n"
            f"Installed to:\n{installed_dirs}",
            border_style="green",
            expand=False,
        )
    )


# Bundled (mantle) ====================================================================


def _bundled_skills_dir(engine: str) -> Path:
    """Return the directory holding bundled skills for *engine*."""
    return Path(__file__).parent / BUNDLED_SKILLS_DIRNAME / engine


def _load_bundled_skills(engine: str) -> List[AgentSkillInfo]:
    """Enumerate and parse the SKILL.md files bundled for *engine*."""
    skills_dir = _bundled_skills_dir(engine)
    if not skills_dir.is_dir():
        return []
    skills: List[AgentSkillInfo] = []
    for skill_dir in sorted(skills_dir.iterdir()):
        skill_file = skill_dir / "SKILL.md"
        if skill_file.is_file():
            skills.append(AgentSkillInfo.from_path(skill_file))
    return skills


def _print_bundled_skills_table(engine_name: str, skills: List[AgentSkillInfo]) -> None:
    """Print a table of the skills bundled with this Rasa version."""
    table = Table(
        title=f"{engine_name} [dim](bundled)[/dim]",
        caption=f"Ships with Rasa {rasa_version} — installs offline, no network.",
        expand=False,
    )
    table.add_column("Skill", style="bold")
    table.add_column("Description")
    for skill in skills:
        table.add_row(skill.name, skill.description or "")

    console.print()
    console.print(table)


def _print_calm_skills_table(skill_names: List[str]) -> None:
    """Print the calm skill names discovered from the GitHub skills repo."""
    table = Table(
        title="calm [dim](GitHub)[/dim]",
        caption=f"From {AGENT_SKILLS_REPO} — fetched at install time.",
        expand=False,
    )
    table.add_column("Skill", style="bold")
    for name in skill_names:
        table.add_row(name)

    console.print()
    console.print(table)


# Calm GitHub fetch (pre-manifest) =====================================================


def _partition_by_compatibility(
    skills: List[AgentSkillInfo],
) -> Tuple[List[AgentSkillInfo], List[AgentSkillInfo]]:
    """Split skills into compatible and incompatible lists."""
    compatible: List[AgentSkillInfo] = []
    incompatible: List[AgentSkillInfo] = []
    for skill in skills:
        if skill.is_compatible_with(rasa_version):
            compatible.append(skill)
        else:
            incompatible.append(skill)
    return compatible, incompatible


def _warn_incompatible_skills(
    incompatible: List[AgentSkillInfo],
    current_ver: str,
) -> None:
    """Print a warning for each incompatible skill."""
    console.print()
    for skill in incompatible:
        console.print(
            f"  [yellow]⚠[/yellow]  [bold]{skill.name}[/bold] was updated "
            f"for Rasa [bold]{skill.rasa_version}[/bold]. "
            f"Your version is [bold]{current_ver}[/bold]."
        )

    console.print()
    console.print(
        Panel(
            "[yellow]⚠[/yellow]  It is [bold]not recommended[/bold] to "
            "install these skills.\n"
            "The agent might use features that are incompatible with your "
            "current Rasa version.\n"
            "To use the new skills, please [bold]update Rasa[/bold].",
            border_style="yellow",
            expand=False,
        )
    )


def _confirm_install_incompatible() -> bool:
    """Ask the user whether to install incompatible skills anyway."""
    answer = questionary.confirm(
        "Install incompatible skills anyway?", default=False
    ).ask()
    restore_blocking_io()
    if answer is None:
        sys.exit(1)
    return answer


def _fetch_skill_names_from_repo() -> List[str]:
    """Fetch available calm skill directory names from the agent-skills repo."""
    url = AGENT_SKILLS_API_URL.format(repo=AGENT_SKILLS_REPO)
    try:
        with urllib.request.urlopen(url, timeout=HTTP_TIMEOUT) as response:
            entries = json.loads(response.read())
        return [entry["name"] for entry in entries if entry["type"] == "dir"]
    except Exception as exc:
        console.print(f"  [red]✖[/red] Could not fetch skill list: {exc}")
        return []


def _download_skills_from_repo(skill_names: List[str]) -> List[AgentSkillInfo]:
    """Download SKILL.md and optional files from `references/` for each skill.

    Returns:
        List of `AgentSkillInfo` objects for successfully downloaded skills. Skills that
        fail to download are skipped with a warning.
    """
    downloaded: List[AgentSkillInfo] = []
    for skill in skill_names:
        url = AGENT_SKILLS_RAW_URL.format(repo=AGENT_SKILLS_REPO, skill=skill)
        try:
            with urllib.request.urlopen(url, timeout=HTTP_TIMEOUT) as resp:
                content = resp.read().decode("utf-8")
            extra_files = _download_skill_reference_files(skill)
            downloaded.append(
                AgentSkillInfo.from_content(skill, content, extra_files=extra_files)
            )
        except Exception as exc:
            console.print(f"  [red]✖[/red] {skill}: {exc}")
    return downloaded


def _download_skill_reference_files(skill: str) -> Dict[str, str]:
    """Download files from a skill's optional `references/` directory.

    Args:
        skill: Skill directory name in the agent-skills repository.

    Returns:
        Mapping of `references/<file>` paths to file contents.
        Empty if the skill has no references or listing fails.
    """
    extra_files: Dict[str, str] = {}
    for entry in _list_skill_references(skill):
        filename = entry.get("name")
        if entry.get("type") != "file" or not isinstance(filename, str):
            continue
        if not _is_safe_reference_filename(filename):
            continue
        file_content = _download_reference_file(skill, filename)
        if file_content is not None:
            extra_files[f"{AGENT_SKILL_REFERENCES_DIR}/{filename}"] = file_content
    return extra_files


def _list_skill_references(skill: str) -> List[Dict[str, Any]]:
    """Return GitHub contents entries for a skill's `references/` directory.

    Args:
        skill: Skill directory name.

    Returns:
        Directory entries from the GitHub Contents API, or an empty list if the
        folder is missing or listing fails.
    """
    url = AGENT_SKILLS_REFERENCES_API_URL.format(
        repo=AGENT_SKILLS_REPO,
        skill=urllib.parse.quote(skill, safe=""),
    )
    try:
        with urllib.request.urlopen(url, timeout=HTTP_TIMEOUT) as response:
            entries = json.loads(response.read())
    except urllib.error.HTTPError as exc:
        if exc.code != 404:
            console.print(
                f"  [yellow]⚠[/yellow]  {skill}: could not list references: {exc}"
            )
        return []
    except Exception as exc:
        console.print(
            f"  [yellow]⚠[/yellow]  {skill}: could not list references: {exc}"
        )
        return []

    if not isinstance(entries, list):
        return []
    return entries


def _download_reference_file(skill: str, filename: str) -> Optional[str]:
    """Download one file from a skill's `references/` directory.

    Args:
        skill: Skill directory name.
        filename: File name inside `references/`.

    Returns:
        File text, or `None` if the download fails.
    """
    url = AGENT_SKILLS_REFERENCE_RAW_URL.format(
        repo=AGENT_SKILLS_REPO,
        skill=urllib.parse.quote(skill, safe=""),
        filename=urllib.parse.quote(filename, safe=""),
    )
    try:
        with urllib.request.urlopen(url, timeout=HTTP_TIMEOUT) as response:
            return response.read().decode("utf-8")
    except Exception as exc:
        console.print(
            f"  [yellow]⚠[/yellow]  {skill}/{AGENT_SKILL_REFERENCES_DIR}/{filename}: "
            f"{exc}"
        )
        return None


def _is_safe_reference_filename(filename: str) -> bool:
    """Return whether `filename` is a single file name with no path parts."""
    return (
        bool(filename)
        and filename not in (".", "..")
        and "/" not in filename
        and "\\" not in filename
    )


def _is_safe_reference_relative_path(relative_path: str) -> bool:
    """Return whether `relative_path` is `references/<file>`."""
    prefix = f"{AGENT_SKILL_REFERENCES_DIR}/"
    if not relative_path.startswith(prefix):
        return False
    return _is_safe_reference_filename(relative_path[len(prefix) :])


# Interactive prompts ==================================================================


def _ask_engine() -> str:
    """Prompt for calm vs mantle."""
    answer = questionary.select(
        "Which Rasa engine does this project use?",
        choices=[
            questionary.Choice("CALM     (flows-based)", value=ENGINE_CALM),
            questionary.Choice("Mantle  (skills-based, beta)", value=ENGINE_MANTLE),
        ],
        style=WIZARD_STYLE,
    ).ask()
    restore_blocking_io()
    if answer is None:
        sys.exit(1)
    return answer


def _ask_ides() -> List[str]:
    """Prompt the user to select which IDEs to install skills for."""
    choices = [
        questionary.Choice(IDE_DISPLAY_NAMES[ide], value=ide) for ide in SUPPORTED_IDES
    ]
    answer = questionary.checkbox(
        "Which IDEs should the skills be installed for?",
        choices=choices,
        style=WIZARD_STYLE,
        validate=lambda selected: (
            True
            if selected
            else "Please select at least one IDE (use Space to select, then Enter)."
        ),
    ).ask()
    restore_blocking_io()
    if answer is None:
        sys.exit(1)
    return answer


def _print_no_ides_hint() -> None:
    """Print the hint shown when no IDEs could be resolved non-interactively."""
    console.print(
        "[yellow]No IDEs specified.[/yellow]\n"
        "Pass [bold]--ides cursor,vscode[/bold] or run "
        "[bold]rasa tools init[/bold] first to save IDE preferences."
    )


# Local file system ====================================================================


def warn_if_agent_skills_exist(project_dir: Path, ides: List[str]) -> None:
    """Warn if agent skills directories exist when skipping installation."""
    existing_dirs = [
        project_dir / base
        for ide, base in IDE_SKILLS_BASE.items()
        if ide in ides
        and (project_dir / base).is_dir()
        and any((project_dir / base).iterdir())
    ]

    if existing_dirs:
        dir_list = "\n".join(f"  • {d}" for d in existing_dirs)
        console.print()
        console.print(
            Panel(
                "[yellow]⚠[/yellow]  [bold]Agent skills detected[/bold]\n\n"
                "You chose not to install agent skills, "
                "but these skill directories already exist:\n\n"
                f"{dir_list}\n\n"
                "If left in the project, your IDE may still load them. "
                "Delete them manually if you no longer need them.",
                border_style="yellow",
                expand=False,
            )
        )


def _find_existing_skills(destinations: Dict[str, Path]) -> List[Path]:
    """Return a list of non-empty skill directories that already exist."""
    return [
        dest_dir
        for dest_dir in destinations.values()
        if dest_dir.is_dir() and any(dest_dir.iterdir())
    ]


def _confirm_overwrite_skills(existing: List[Path]) -> bool:
    """Ask the user whether to overwrite existing agent skills."""
    dir_list = "\n".join(f"  • {d}" for d in existing)
    console.print()
    console.print(
        Panel(
            "[yellow]⚠[/yellow]  [bold]Agent skills already installed[/bold]\n\n"
            "The following skill directories already exist:\n\n"
            f"{dir_list}\n\n"
            "Continuing will overwrite them with the latest versions.",
            border_style="yellow",
            expand=False,
        )
    )
    answer = questionary.confirm("Overwrite existing skills?", default=False).ask()
    restore_blocking_io()
    if answer is None:
        sys.exit(1)
    return answer


def _write_skills_to_disk(
    skills: List[AgentSkillInfo],
    destinations: Dict[str, Path],
    incompatible_names: Optional[Set[str]] = None,
) -> None:
    """Write skill files to each IDE destination and print progress."""
    flagged = incompatible_names or set()
    max_name_len = max((len(s.name) for s in skills), default=0)

    for skill in skills:
        for dest_dir in destinations.values():
            _write_skill_directory(dest_dir / skill.name, skill)

        ide_labels = ", ".join(IDE_DISPLAY_NAMES.get(ide, ide) for ide in destinations)
        padded_name = skill.name.ljust(max_name_len)
        if skill.name in flagged:
            console.print(
                f"  [green]✔[/green] [yellow]⚠[/yellow]  "
                f"{padded_name}  →  {ide_labels}"
            )
            console.print(
                f"       [yellow]╰─ requires Rasa {skill.rasa_version}"
                ", incompatible with your version[/yellow]"
            )
        else:
            indicator = "[green]✔[/green]  "
            console.print(f"  {indicator}  {padded_name}  →  {ide_labels}")


def _write_skill_directory(skill_dir: Path, skill: AgentSkillInfo) -> None:
    """Write `SKILL.md` and any `references/` files under `skill_dir`."""
    skill_dir.mkdir(parents=True, exist_ok=True)
    (skill_dir / AGENT_SKILL_ENTRYPOINT).write_text(skill.content, encoding="utf-8")

    for relative_path, file_content in skill.extra_files.items():
        if not _is_safe_reference_relative_path(relative_path):
            continue
        filename = relative_path.split("/", 1)[1]
        dest = skill_dir / AGENT_SKILL_REFERENCES_DIR / filename
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(file_content, encoding="utf-8")
